diff --git a/crates/agents/src/rail.rs b/crates/agents/src/rail.rs
index 7d33d9b28..6025f6ab1 100644
--- a/crates/agents/src/rail.rs
+++ b/crates/agents/src/rail.rs
@@ -42,10 +42,16 @@ pub(super) struct ClosedPreparation {

 impl Rail {
     pub fn open(path: &Path) -> Result<Self, OpenError> {
+        let measured = std::time::Instant::now();
         let mut db = Connection::open(path)?;
+        eprintln!("probe crates/agents/src/rail.rs let mut db = Connection::open(path)?;: {:.6}", measured.elapsed().as_secs_f64()*1e3);
         db.set_transaction_behavior(rusqlite::TransactionBehavior::Immediate);
+        let measured = std::time::Instant::now();
         db.pragma_update(None, "journal_mode", "WAL")?;
+        eprintln!("probe crates/agents/src/rail.rs db.pragma_update(None, 'journal_mode', 'WAL')?;: {:.6}", measured.elapsed().as_secs_f64()*1e3);
+        let measured = std::time::Instant::now();
         crate::schema::open(&mut db, path)?;
+        eprintln!("probe crates/agents/src/rail.rs crate::schema::open(&mut db, path)?;: {:.6}", measured.elapsed().as_secs_f64()*1e3);
         // Terminal ids restart at 1 with the Daemon, so a stored id could name an unrelated Terminal.
         db.execute("UPDATE nodes SET terminal_id = NULL", [])?;
         // A25: a Rail stored by an earlier Daemon holds `room` where this one writes `workstream`.
