--- a/crates/agents/src/rail/measurement.rs
+++ b/crates/agents/src/rail/measurement.rs
@@ -280,7 +280,9 @@ impl Drop for MeasurementWait {

 impl Timing {
     pub(crate) fn open(path: &Path, bus: Bus, clock: crate::Clock) -> Result<Self, OpenError> {
+        let measured = std::time::Instant::now();
         let db = Connection::open(path)?;
+        eprintln!("probe crates/agents/src/rail/measurement.rs let db = Connection::open(path)?;: {:.6}", measured.elapsed().as_secs_f64()*1e3);
         // A busy measurement store reports a collection failure; it cannot hold up an
         // acknowledgement/answer waiting for a writer in the Agent lifecycle.
         db.busy_timeout(Duration::ZERO)?;
